/** Static installed mod. No descriptor, token or source-checkout path is embedded. */
export const claudeNativePluginFiles = {
  'plugin/hooks/native-incoming.js': String.raw`// Generated by NCF Agent Interconnect. Do not edit.
const source = 'ncf-agent-interconnect';
const triggerPrefix = 'NCF native incoming admission: ';
const uuid = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i;
const key = /^[a-f0-9]{64}$/;
const current = (own) => !!own && own.current;

export function startNative(own) {
  own.nativePending = new Map();
  own.nativePreparing = new Set();
}

export function endNative(own) {
  own.nativePending.clear();
  own.nativePreparing.clear();
}

async function post($, descriptor, route, value) {
  const response = await $.http.fetch(new URL('/integrations/claude/native/' + route, descriptor.url).href, {
    method: 'POST',
    headers: { 'content-type': 'application/json', authorization: 'Bearer ' + descriptor.token },
    body: JSON.stringify(value),
  });
  if (!response.ok) throw new Error('NCF native admission request was refused');
  return JSON.parse(response.text);
}

async function report($, own, pending, phase, witness = {}) {
  const result = await post($, pending.descriptor, 'report', {
    sessionId: pending.sessionId, delivery: pending.delivery, reportKey: pending.reportKey,
    phase, ...witness,
  });
  if (current(own) && own.nativePending.get(pending.delivery) === pending &&
      ['committed', 'cancelled', 'uncertain'].includes(result.state))
    own.nativePending.delete(pending.delivery);
  return result;
}

export async function submitNative($, own, descriptor, sessionId, wake) {
  if (!current(own) || typeof wake.claim !== 'string' || !key.test(wake.claim) ||
      own.nativePreparing.has(wake.claim)) return;
  own.nativePreparing.add(wake.claim);
  let pending = null;
  try {
    const prepared = await post($, descriptor, 'prepare', { sessionId, claim: wake.claim });
    if (typeof prepared.delivery !== 'string' || !uuid.test(prepared.delivery) ||
        prepared.trigger !== triggerPrefix + prepared.delivery ||
        typeof prepared.reportKey !== 'string' || !key.test(prepared.reportKey) ||
        !Array.isArray(prepared.representationHashes) || prepared.representationHashes.length < 1 ||
        prepared.representationHashes.length > 4 ||
        !prepared.representationHashes.every((hash) => typeof hash === 'string' && key.test(hash)))
      return;
    pending = { ...prepared, descriptor, sessionId, observing: false };
    if (!current(own)) {
      await report($, own, pending, 'not-submitted');
      return;
    }
    own.nativePending.set(pending.delivery, pending);
    // Only the separate native gate can replace this exact one-use trigger
    // with a node-owned full message. Never submit a read instruction or asUser.
    const result = await $.prompt.submit({ text: prepared.trigger });
    if (result && typeof result.drop === 'string') await report($, own, pending, 'dropped');
    // Queue/start/submit resolution never creates receipt. The stored-row hook does.
    if (own.nativePending.get(pending.delivery) === pending) {
      await report($, own, pending, 'uncertain').catch(() => {});
      own.nativePending.delete(pending.delivery);
    }
  } catch {
    if (pending) {
      await report($, own, pending, 'uncertain').catch(() => {});
      own.nativePending.delete(pending.delivery);
    }
  } finally {
    own.nativePreparing.delete(wake.claim);
  }
}

async function rowHash(message) {
  if (message.name !== undefined || !Array.isArray(message.content) ||
      !message.content.every((block) => block && block.type === 'text' &&
        typeof block.text === 'string' && Object.keys(block).every((key) => key === 'type' || key === 'text')))
    return null;
  const value = JSON.stringify({
    type: message.type, role: message.role, isMeta: message.isMeta === true,
    content: message.content.map((block) => ({ type: block.type, text: block.text })),
  });
  const hash = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value));
  return [...new Uint8Array(hash)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

export function registerNative(on, getScope) {
  on('session.append', async ($, e, next) => {
    const own = getScope();
    if (!current(own) || e.door !== 'prompt' || e.agentId ||
        e.origin?.kind !== 'plugin' || e.origin.name !== source || e.origin.asUser === true ||
        typeof e.uuid !== 'string' || !e.uuid || !e.message ||
        e.message.type !== 'user' || e.message.role !== 'user' || e.message.isMeta === true)
      return next(e);
    const inputHash = await rowHash(e.message);
    if (!current(own)) return next(e);
    const pending = [...own.nativePending.values()].find((value) =>
      !value.observing && value.representationHashes.includes(inputHash));
    if (!pending) return next(e);
    pending.observing = true;
    try {
      if (!current(own) || !pending.representationHashes.includes(inputHash)) {
        const result = await next(e);
        await report($, own, pending, 'uncertain').catch(() => {});
        return result;
      }
      const result = await next(e);
      if (!current(own)) return result;
      const sessionId = await $.session.id();
      if (!current(own) || sessionId !== pending.sessionId) return result;
      if (!result || result.uuid !== e.uuid || !result.message ||
          result.message.type !== 'user' || result.message.role !== 'user' ||
          result.message.isMeta === true) {
        await report($, own, pending, 'uncertain').catch(() => {});
        return result;
      }
      const representationHash = await rowHash(result.message);
      if (!current(own)) return result;
      if (!pending.representationHashes.includes(representationHash)) {
        await report($, own, pending, 'uncertain').catch(() => {});
        return result;
      }
      await report($, own, pending, 'stored', { storedRowId: result.uuid, representationHash }).catch(() => {});
      return result;
    } catch (error) {
      await report($, own, pending, 'uncertain').catch(() => {});
      throw error;
    }
  });
}
`,
};
